export function expiringSoon(wallet: Wallet, day: number, within: number): number {
  if (within <= 0) return 0;
  const target = day + within;
  let total = 0;
  for (const batch of wallet.batches) {
    const expiry = batch.bought + TOKEN_LIFE_DAYS;
    const spendableNow = batch.bought <= day && day < expiry;
    const deadLater = target >= expiry;
    if (spendableNow && deadLater) total += batch.left;
  }
  return total;
}
